"""Generate reviewable, rerunnable SQL and a data-plane import payload. No DB I/O."""
import json
from pathlib import Path
from equinox_data import ABILITIES, NOTES, parameters

ROOT = Path(__file__).resolve().parents[2]


def sql(value):
    if value is None:
        return 'null'
    if isinstance(value, (int, float)):
        return str(value)
    return "'" + str(value).replace("'", "''") + "'"


def main():
    payload = []
    lines = [
        '-- Generated by DB/Seeds/export_equinox_update.py; rerunnable DML only.',
        '-- Equinox rank-3 parameters + five missing cultivation doctrines.',
        '-- Existing nonempty lore and identity fields are preserved. No inventory edits.',
        'begin;',
    ]
    for name in ABILITIES:
        rows = parameters(name)
        entry = dict(ability_name=name, wiki_title=name.replace(' ', '_'), notes=NOTES[name], parameters=rows)
        payload.append(entry)
        lines.append('insert into wf_base.ability_catalog (ability_name, wiki_title, notes, last_ingested_at) values (' +
                     ', '.join([sql(name), sql(entry['wiki_title']), sql(NOTES[name]), 'now()']) +
                     ') on conflict (ability_name) do update set wiki_title=excluded.wiki_title, notes=excluded.notes, last_ingested_at=excluded.last_ingested_at;')
        for row in rows:
            columns = list(row)
            lines.append('insert into wf_base.ability_parameters (ability_catalog_id, ' + ', '.join(columns) +
                         ') select ability_catalog_id, ' + ', '.join(sql(row[k]) for k in columns) +
                         ' from wf_base.ability_catalog where ability_name=' + sql(name) +
                         ' on conflict (ability_catalog_id, parameter_key, context) do update set ' +
                         ', '.join(k + '=excluded.' + k for k in columns if k not in ('parameter_key', 'context')) + ';')
    lore = json.loads((ROOT / 'DB/Cultivation/missing_doctrines_20261121.json').read_text(encoding='utf-8'))
    for entry in lore:
        lines.append('update wf_user.my_frames set ' + ', '.join(
            k + '=case when ' + k + " is null or lower(btrim(" + k + ")) in ('', 'nan', 'null') then " + sql(v) + ' else ' + k + ' end'
            for k, v in entry.items() if k.startswith('cultivation_')) +
            ' where my_frame_id=' + str(entry['my_frame_id']) +
            ' and warframe_id=' + str(entry['warframe_id']) +
            ' and build_title=' + sql(entry['build_title']) +
            " and (cultivation_doctrine is null or lower(btrim(cultivation_doctrine)) in ('', 'nan', 'null'));" )
    lines += ['commit;', '-- Verify after applying:',
              'select my_frame_id, build_title, cultivation_school, cultivation_art from wf_user.my_frames where my_frame_id between 118 and 122 order by my_frame_id;',
              "select a.ability_name, count(p.*) from wf_base.ability_catalog a join wf_base.ability_parameters p using (ability_catalog_id) where a.ability_name in ('Metamorphosis','Rest & Rage','Pacify & Provoke','Mend & Maim') group by a.ability_name;"]
    out = ROOT / 'DB/StaticData/equinox_20261121.json'
    out.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
    (ROOT / 'DB/Migrations/20261121_equinox_and_missing_doctrines.sql').write_text('\n\n'.join(lines) + '\n', encoding='utf-8')
    print('Exported', len(payload), 'abilities,', sum(len(x['parameters']) for x in payload), 'parameters,', len(lore), 'doctrines')


if __name__ == '__main__':
    main()
